CREATE TABLE users(id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, passwordHash TEXT NOT NULL, createdAt TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(tokenHash TEXT PRIMARY KEY, userId INTEGER NOT NULL REFERENCES users(id), expiresAt INTEGER NOT NULL);
CREATE TABLE audience_profiles(id INTEGER PRIMARY KEY, ownerId INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, ageMin INTEGER, ageMax INTEGER, country TEXT, language TEXT, interests TEXT DEFAULT '[]', preferredDurationSec TEXT, tone TEXT, avoid TEXT DEFAULT '[]', createdAt TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE brands(id INTEGER PRIMARY KEY, ownerId INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, handle TEXT, description TEXT, targetAgeMin INTEGER, targetAgeMax INTEGER, targetGender TEXT, country TEXT, language TEXT, secondaryLanguages TEXT DEFAULT '[]', niche TEXT, audienceProfileId INTEGER REFERENCES audience_profiles(id), tone TEXT, visualStyle TEXT, contentRules TEXT, prohibitedTopics TEXT DEFAULT '[]', preferredTopics TEXT DEFAULT '[]', postingFrequency TEXT, active INTEGER DEFAULT 1, createdAt TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE content_items(id INTEGER PRIMARY KEY, ownerId INTEGER NOT NULL REFERENCES users(id), brandId INTEGER NOT NULL REFERENCES brands(id), title TEXT NOT NULL, topic TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', aiGenerated INTEGER NOT NULL DEFAULT 1, createdAt TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY, userId INTEGER, action TEXT, entity TEXT, entityId INTEGER, createdAt TEXT DEFAULT CURRENT_TIMESTAMP);
